// ==========
// SAFE PARSERS + FORMATTERS
// ==========
function toNumber(value) {
    if (value === null || value === undefined) return 0;
    try {
        value = value.toString().replace(/[^0-9.\-]/g, '');
        var n = parseFloat(value);
        return isNaN(n) ? 0 : n;
    } catch (e) {
        return 0;
    }
}

function currencyView(data) {
    data = (data || 0) * 1;
    if (!data) return '$0';
    return '$' + (Math.round(data)).toLocaleString('en-IN');
}

// Round to nearest integer
function customRound(data) {
    return Math.round(data);
}

// Round up/down to nearest 100
function roundUpToHundred(v) {
    v = +v || 0;
    return (v >= 0) ? Math.ceil(v / 100) * 100 : Math.floor(v / 100) * 100;
}
function roundDownToHundred(v) {
    v = +v || 0;
    return (v >= 0) ? Math.floor(v / 100) * 100 : Math.ceil(v / 100) * 100;
}

function showTotalGrossManagementFee() {
    var fee = toNumber(ctrlManageFee.getValue());
    // Read GST rate dynamically
    var gstRateRaw = toNumber(ctrlGstRate.getValue());
    var gstPercent = gstRateRaw; 

    var gstPayableOn = (ctrlGstPayable.getValue() == "on");
    var gstInclusive = (ctrlGstInclusive.getValue() == "on");

    var earned = 0, gstAmount = 0, gross = 0, salespersonEarned = 0;

    // Case 1: GST chargeable (exclusive)
    if (gstPayableOn && !gstInclusive) {
        gstAmount = fee * gstPercent / 100;
        earned = fee;
        gross = fee + gstAmount;
        salespersonEarned = gross;

    // Case 2: GST chargeable but fee is GST-inclusive
    } else if (gstPayableOn && gstInclusive) {
        gstAmount = fee * gstPercent / (100 + gstPercent);
        earned = fee - gstAmount; // net of GST
        gross = fee;
        salespersonEarned = fee;

    // Case 3: GST NOT applicable
    } else {
        earned = fee;
        gstAmount = 0;
        gross = fee;
        salespersonEarned = fee;
    }

    // Final rounding
    earned = customRound(earned);
    gstAmount = customRound(gstAmount);
    gross = customRound(gross);
    salespersonEarned = customRound(salespersonEarned);

    // Update PHPRunner fields
    ctrlGross.setValue(gross);
    ctrlGstAgency.setValue(gstAmount);
    ctrlCommEarnedSalesperson.setValue(salespersonEarned);

    $('#readonly_value_comm_earned_1').text(currencyView(earned));
    $('#readonly_value_gst_1').text(currencyView(gstAmount));
    $('#readonly_value_comm_gross_1').text(currencyView(gross));
    $('#readonly_value_gst_agency_1').text(currencyView(gstAmount));
    
    refreshTableData();
    refreshExternalCoBroker();
    refreshInternalCoBroker();
}

// ==========================
// MANAGEMENT FEE EVENT BINDING
// ==========================
if (ctrlManageFee && typeof ctrlManageFee.on === 'function') {
    ctrlManageFee.on('keyup', showTotalGrossManagementFee);
    ctrlManageFee.on('change', showTotalGrossManagementFee);
}

if (ctrlGstRate && typeof ctrlGstRate.on === 'function') {
    ctrlGstRate.on('keyup', showTotalGrossManagementFee);
    ctrlGstRate.on('change', showTotalGrossManagementFee);
}

if (ctrlGstPayable && typeof ctrlGstPayable.on === 'function') {
    ctrlGstPayable.on('change', showTotalGrossManagementFee);
}

if (ctrlGstInclusive && typeof ctrlGstInclusive.on === 'function') {
    ctrlGstInclusive.on('change', showTotalGrossManagementFee);
}

// Consultation fee → commission
if (ctrlConsultFee && typeof ctrlConsultFee.on === 'function') {
  ctrlConsultFee.on('keyup', function () {
    var consultfee = toNumber(ctrlConsultFee.getValue());
    if (isNaN(consultfee)) {
      ctrlAmount.setValue('');
      return;
    }
    ctrlAmount.setValue(Math.round(consultfee));
    showTotalGrossManagementFee(); // recalc with consultation fee
  });
}

// Unit → amount
if (ctrlUnit && typeof ctrlUnit.on === 'function') {
  ctrlUnit.on('keyup', function () {
    var unit = toNumber(ctrlUnit.getValue());
    if (isNaN(unit)) {
      ctrlAmount.setValue('');
      return;
    }
    var transacted = toNumber(ctrlTransacted.getValue());
    ctrlAmount.setValue(Math.round(transacted * unit));
    showTotalGrossManagementFee();
  });
}

// Amount → unit & percent
if (ctrlAmount && typeof ctrlAmount.on === 'function') {
  ctrlAmount.on('keyup', function () {
    var amount = toNumber(ctrlAmount.getValue());
    if (isNaN(amount)) {
      ctrlUnit.setValue('');
      ctrlPercent.setValue('');
      return;
    }
    var transacted = toNumber(ctrlTransacted.getValue());
    if (transacted) {
      ctrlUnit.setValue((amount / transacted).toFixed(2));
      ctrlPercent.setValue(((amount / transacted) * 100).toFixed(2));
    } else {
      ctrlUnit.setValue('');
      ctrlPercent.setValue('');
    }
    showTotalGrossManagementFee();
  });
}

// Percent → amount
